-- Converted: CREATE INDEX (Teradata NUSI on status) -> clustering key on SALES.CUSTOMER (status).
-- Reason: Snowflake CREATE INDEX applies only to hybrid tables; status is a low-cardinality filter column, which suits micro-partition pruning via a clustering key better than search optimization (meant for selective point lookups).
ALTER TABLE SALES.CUSTOMER CLUSTER BY (status);

-- Converted: CREATE UNIQUE INDEX (Teradata USI on customer_id) -> informational UNIQUE constraint named IX_ACCOUNT_CUSTOMER.
-- Reason: Snowflake standard tables do not support CREATE INDEX; the UNIQUE constraint documents the key for tools and the optimizer (RELY) but is not enforced.
ALTER TABLE SALES."ACCOUNT" ADD CONSTRAINT IX_ACCOUNT_CUSTOMER UNIQUE (customer_id) RELY;

-- Converted: unique-index lookup path -> search optimization for equality predicates on customer_id.
-- Reason: search optimization is the Snowflake service for selective point lookups, which is what a USI provides in Teradata.
ALTER TABLE SALES."ACCOUNT" ADD SEARCH OPTIMIZATION ON EQUALITY(customer_id);

-- Converted: CREATE HASH INDEX (account_id) BY (customer_id) -> search optimization on account_id.
-- Reason: a hash index provides a fast lookup structure on account_id; search optimization is the Snowflake equivalent for selective equality lookups.
