-- Converted: hash index row distribution BY (customer_id) -> clustering key on customer_id.
-- Reason: BY (customer_id) co-locates index rows by customer; a clustering key co-locates micro-partitions by customer_id in large tables.
ALTER TABLE SALES."ACCOUNT" CLUSTER BY (customer_id);

