-- Converted: CREATE PROCEDURE (Teradata SPL) -> CREATE OR REPLACE PROCEDURE ... LANGUAGE SQL Snowflake Scripting block with RETURNS VARCHAR and EXECUTE AS OWNER (from SQL SECURITY OWNER).
-- Reason: Snowflake procedures require a RETURNS clause and an explicit EXECUTE AS (snowflake.rule.procedure_execute_as); parameters are referenced with a colon prefix inside SQL.
CREATE OR REPLACE PROCEDURE SALES.ADD_PAYMENT(p_account BIGINT, p_amount NUMBER(12, 2))
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS
$$
BEGIN
    -- Converted: two implicit-transaction INSERTs -> one explicit transaction with rollback on error.
    -- Reason: keeps the payment and its audit row atomic; only DML is inside the transaction.
    BEGIN TRANSACTION;
    -- Converted: parameter references p_account/p_amount -> bind references :p_account/:p_amount.
    -- Reason: Snowflake Scripting variables in SQL statements are referenced with a colon prefix.
    INSERT INTO SALES.PAYMENT (payment_id, account_id, amount)
        VALUES (1, :p_account, :p_amount);
    -- Converted: unchanged INSERT, target name from naming map.
    -- Reason: standard SQL INSERT is identical in Snowflake.
    INSERT INTO SALES.AUDIT_LOG (event_id, event_type)
        VALUES (1, 'PAYMENT');
    COMMIT;
    RETURN 'OK';
EXCEPTION
    WHEN OTHER THEN
        ROLLBACK;
        RAISE;
END;
$$;

